INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('4af1f211-13f1-5244-9a2e-0f1ac671195a', 'd77ca462-57cb-529b-9c75-1db17367525d', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 2, 'Meaningful recurring fee revenue', 'Trailing-30d user-paid fees (DefiLlama or equivalent) at a level that would rank the chain among top fee-generating networks; fees paid by end users, not validator self-dealing.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('83d32c15-2183-5ad3-befe-c2a719bab7dc', 'd77ca462-57cb-529b-9c75-1db17367525d', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 3, 'Usage persists without heavy incentives', 'Onchain activity and fee revenue persist through a >12-month drawdown or after major incentive programs end, without collapsing >80%.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('84019e89-a2e7-5713-a504-00226c1f8418', 'd77ca462-57cb-529b-9c75-1db17367525d', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 4, 'External institutions operationally depend on it', 'Named institutions running production workloads that depend on the chain (settlement, tokenized assets, enterprise apps) — live operations, not pilots or announcements.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('a7c9126c-d2b0-5430-b546-9ac43d1a36d8', 'd77ca462-57cb-529b-9c75-1db17367525d', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 5, 'Dominant execution layer', 'The chain is the default settlement/execution venue for its category by multiple independent measures (fees, developer share, tokenized value).');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('6fe704fe-e595-54a0-a4ca-7dc93efe21ce', 'd77ca462-57cb-529b-9c75-1db17367525d', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 0, 'Functional network exists', 'Genesis block / network launch; blocks propagating.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('723e36df-033d-5e7b-91fd-486c609b52fa', 'd77ca462-57cb-529b-9c75-1db17367525d', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 1, 'Independent users hold and transact', 'Non-trivial holder base, exchange listings, peer-to-peer transfers beyond the founding team.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('039aed97-f0e5-5ec7-8637-061afb0b4dd0', 'd77ca462-57cb-529b-9c75-1db17367525d', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 2, 'Survives a full market cycle intact', 'A >70% price drawdown occurs while onchain holder count, hash rate/security budget, and development do not collapse.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('200d9281-e5ca-5711-aea1-2c036da2410c', 'd77ca462-57cb-529b-9c75-1db17367525d', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 3, 'Institutional allocation as treasury/reserve asset', 'Public companies, funds, or sovereigns disclose the asset on balance sheets or in regulated investment products.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('97ae45cb-1ca8-5a51-a29e-fe14145d954e', 'd77ca462-57cb-529b-9c75-1db17367525d', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 4, 'Unit of account / widespread medium of exchange', 'Priced and lent against broadly; used as a unit of account in real commerce beyond niche merchants.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('f7536ebc-9ae6-5499-9cad-32e110c09f02', 'd77ca462-57cb-529b-9c75-1db17367525d', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 5, 'Global monetary asset', 'Central banks or sovereign wealth funds hold it as a reserve asset class alongside gold/FX reserves.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('f44e0457-8846-5c09-9d77-c4dc0a2a98e7', 'd77ca462-57cb-529b-9c75-1db17367525d', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 0, 'Functional oracle network exists', 'Decentralized oracle network live, publishing price/data feeds consumed onchain.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('411a0425-f4c0-527f-8c02-218ed9455de7', 'd77ca462-57cb-529b-9c75-1db17367525d', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 1, 'Independent protocols consume feeds', 'Third-party protocols integrating feeds for production use (lending, derivatives, stablecoins).');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('8dc9f3e9-c270-5efa-aba5-e6a44537f030', 'd77ca462-57cb-529b-9c75-1db17367525d', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 2, 'Meaningful fee revenue from data consumers', 'Sustained fee payments from data consumers to node operators/stakers, visible in protocol economics disclosures.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('3d902049-2c98-5b43-8b2c-36985683f781', 'd77ca462-57cb-529b-9c75-1db17367525d', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 3, 'Dominant share of oracle-secured value', 'Clear majority share of oracle-secured onchain value across chains; competitors have not displaced it over a full cycle.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('662b98b2-8c2b-5390-b1b7-675452ed33a6', 'd77ca462-57cb-529b-9c75-1db17367525d', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 4, 'Institutions operationally depend on the feeds', 'Banks, market infrastructure, or enterprises using the feeds in production systems — live operations, not pilots.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('37387f70-7e86-5f18-b1d8-0b85372f71b4', 'd77ca462-57cb-529b-9c75-1db17367525d', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 5, 'Standard oracle infrastructure', 'The network is the default oracle layer for tokenized global finance across asset classes.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('6ee40aa6-11c6-55b0-becc-fafc9808a6c8', 'd77ca462-57cb-529b-9c75-1db17367525d', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 0, 'Functional network exists', 'Ledger live and settling payment transactions.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('a5e06db3-06e2-5da4-9760-2dd2219aeeec', 'd77ca462-57cb-529b-9c75-1db17367525d', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 1, 'Independent users transact', 'Payments by users beyond the founding team; wallet/exchange support.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('8e67533f-a565-5360-aa9e-0a67d45aac1c', 'd77ca462-57cb-529b-9c75-1db17367525d', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 2, 'Meaningful recurring settlement volume', 'Recurring cross-border settlement volume attributable to the rail, disclosed by operators or visible onchain, sustained >6 months.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('7b5c43c6-c6e5-5a00-ba27-f8088f03653f', 'd77ca462-57cb-529b-9c75-1db17367525d', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 3, 'Volume persists without issuer subsidies', 'Volume persists after issuer incentives, rebates, or subsidized corridors end.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('ee3d66c7-19bd-5b35-b1da-442645fab145', 'd77ca462-57cb-529b-9c75-1db17367525d', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 4, 'Institutions operationally depend on the rail', 'Named banks or payment institutions running production settlement flows on the rail — live operations, not pilots or MOUs.');
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('52316e98-5270-524f-9ca0-de10d342eadb', 'd77ca462-57cb-529b-9c75-1db17367525d', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 5, 'Meaningful market penetration', 'The rail handles a measurable share of addressable cross-border payment volume in its target corridors.');
